import java.util.Arrays;

public class ArrayBasics {

    // --- 原地删除：双指针覆盖（LeetCode 283 Move Zeroes 风格）---
    // 把非零元素前移到数组前部，剩余位置置零
    public static void moveZeros(int[] arr) {
        int write = 0; // 写指针：下一个非零元素该放的位置
        for (int read = 0; read < arr.length; read++) {
            if (arr[read] != 0) {
                arr[write++] = arr[read];
            }
        }
        while (write < arr.length) {
            arr[write++] = 0;
        }
    }

    // --- 前缀和：O(1) 区间求和 ---
    public static int[] buildPrefix(int[] arr) {
        int[] prefix = new int[arr.length + 1]; // prefix[0] = 0 哨兵
        for (int i = 0; i < arr.length; i++) {
            prefix[i + 1] = prefix[i] + arr[i];
        }
        return prefix;
    }

    public static int rangeSum(int[] prefix, int l, int r) {
        return prefix[r + 1] - prefix[l]; // O(1)
    }

    // --- 差分数组：O(1) 区间更新 ---
    public static void rangeAdd(int[] diff, int l, int r, int val) {
        diff[l] += val;
        if (r + 1 < diff.length) diff[r + 1] -= val;
    }

    // 差分数组还原为原数组
    public static int[] diffToOriginal(int[] diff) {
        int[] arr = new int[diff.length];
        arr[0] = diff[0];
        for (int i = 1; i < diff.length; i++) {
            arr[i] = arr[i - 1] + diff[i];
        }
        return arr;
    }

    public static void main(String[] args) {
        // 演示前缀和
        int[] arr = {1, 3, 5, 7, 9};
        int[] prefix = buildPrefix(arr);
        System.out.println("sum[1..3] = " + rangeSum(prefix, 1, 3)); // 3+5+7 = 15

        // 演示差分
        int[] diff = new int[5]; // 初始全 0
        rangeAdd(diff, 1, 3, 2); // [1,3] 区间 +2
        rangeAdd(diff, 0, 2, 1); // [0,2] 区间 +1
        System.out.println("after range add: " + Arrays.toString(diffToOriginal(diff)));
        // 结果: [1, 3, 3, 2, 0]
    }
}
